package engine;
import java.lang.reflect.*;
import java.util.*;
/** LeetCode数据与用户对象之间的桥；不依赖用户的具体实现。 */
public final class Bridge {
 final ClassLoader loader; final String pkg; final int id;
 Bridge(ClassLoader l,String p,int id){loader=l;pkg=p;this.id=id;}
 Class<?> type(String n)throws Exception{return Class.forName(pkg.isEmpty()?n:pkg+"."+n,true,loader);}
 static Field field(Class<?> c,String n)throws Exception{Field f=c.getDeclaredField(n);f.setAccessible(true);return f;}
 static Object get(Object x,String n)throws Exception{return x==null?null:field(x.getClass(),n).get(x);}
 static void set(Object x,String n,Object v)throws Exception{field(x.getClass(),n).set(x,v);}
 static int num(Object x){return ((Number)x).intValue();}
 Object node(Class<?> c,int v)throws Exception{Constructor<?> k=c.getDeclaredConstructor(int.class);k.setAccessible(true);return k.newInstance(v);}
 Object construct(Class<?> c,List<?> values)throws Exception{for(Constructor<?> k:c.getDeclaredConstructors())if(k.getParameterCount()==values.size()){k.setAccessible(true);return k.newInstance(convertArgs(values,k.getGenericParameterTypes()));}throw new IllegalArgumentException("构造参数不匹配 "+c);}
 Object[] convertArgs(List<?> a,Type[] ts)throws Exception{Object[] out=new Object[ts.length];for(int i=0;i<out.length;i++)out[i]=convert(a.get(i),ts[i]);return out;}
 Object convert(Object o,Type t)throws Exception{
  if(t instanceof ParameterizedType pt){List<Object> out=new ArrayList<>();for(Object e:(List<?>)o)out.add(convert(e,pt.getActualTypeArguments()[0]));return out;}
  Class<?> c=(Class<?>)t;if(o==null)return null;
  if(c==int.class||c==Integer.class)return num(o);if(c==long.class||c==Long.class)return ((Number)o).longValue();if(c==double.class||c==Double.class)return ((Number)o).doubleValue();if(c==boolean.class||c==Boolean.class)return o;if(c==String.class)return o.toString();if(c==char.class||c==Character.class)return o.toString().charAt(0);
  if(c.isArray()){List<?> a=(List<?>)o;Object v=Array.newInstance(c.getComponentType(),a.size());for(int i=0;i<a.size();i++)Array.set(v,i,convert(a.get(i),c.getComponentType()));return v;}
  if(c.getSimpleName().equals("ListNode")){Object head=null,tail=null;for(Object e:(List<?>)o){Object x=node(c,num(e));if(head==null)head=x;else set(tail,"next",x);tail=x;}return head;}
  if(c.getSimpleName().equals("TreeNode")||c.getSimpleName().equals("Node")&&id==117)return tree((List<?>)o,c);
  if(c.getSimpleName().equals("Node")&&id==138){List<?> a=(List<?>)o;List<Object> ns=new ArrayList<>();for(Object e:a)ns.add(node(c,num(((List<?>)e).get(0))));for(int i=0;i<ns.size();i++){if(i+1<ns.size())set(ns.get(i),"next",ns.get(i+1));Object x=((List<?>)a.get(i)).get(1);if(x!=null)set(ns.get(i),"random",ns.get(num(x)));}return ns.isEmpty()?null:ns.get(0);}
  if(c.getSimpleName().equals("Node")&&id==133){List<?> a=(List<?>)o;List<Object> ns=new ArrayList<>();for(int i=0;i<a.size();i++)ns.add(node(c,i+1));for(int i=0;i<a.size();i++){List<Object> edges=new ArrayList<>();for(Object n:(List<?>)a.get(i))edges.add(ns.get(num(n)-1));set(ns.get(i),"neighbors",edges);}return ns.isEmpty()?null:ns.get(0);}
  throw new IllegalArgumentException("未适配类型 "+t);
 }
 Object tree(List<?> a,Class<?> c)throws Exception{if(a.isEmpty()||a.get(0)==null)return null;Object root=node(c,num(a.get(0)));Queue<Object>q=new ArrayDeque<>();q.add(root);int i=1;while(i<a.size()&&!q.isEmpty()){Object x=q.remove();for(String side:List.of("left","right")){if(i>=a.size())break;Object val=a.get(i++);if(val!=null){Object ch=node(c,num(val));set(x,side,ch);q.add(ch);}}}return root;}
 List<Object> nodes(Object head,String link)throws Exception{List<Object> a=new ArrayList<>();Set<Object> seen=Collections.newSetFromMap(new IdentityHashMap<>());while(head!=null){if(!seen.add(head))break;a.add(head);if(a.size()>200000)throw new IllegalStateException("节点数量异常");head=get(head,link);}return a;}
 Object find(Object root,int v)throws Exception{if(root==null)return null;if(num(get(root,"val"))==v)return root;Object x=find(get(root,"left"),v);return x!=null?x:find(get(root,"right"),v);}
 Method method(Class<?> c,String name,int n){for(Method m:c.getDeclaredMethods())if(m.getName().equals(name)&&m.getParameterCount()==n){m.setAccessible(true);return m;}throw new IllegalArgumentException("找不到方法 "+name);}
 public Object run(Map<String,Object> meta,List<?> in)throws Exception{
  if(Boolean.TRUE.equals(meta.get("systemdesign"))){Class<?> c=type((String)meta.get("classname"));List<?> ops=(List<?>)in.get(0),args=(List<?>)in.get(1);Object obj=construct(c,(List<?>)args.get(0));List<Object> out=new ArrayList<>();out.add(null);Set<Integer> live=new HashSet<>();for(int i=1;i<ops.size();i++){String op=ops.get(i).toString();List<?> a=(List<?>)args.get(i);Method m=method(c,op,a.size());Object v=m.invoke(obj,convertArgs(a,m.getGenericParameterTypes()));if(id==380){if(op.equals("insert"))live.add(num(a.get(0)));if(op.equals("remove"))live.remove(num(a.get(0)));if(op.equals("getRandom")){if(!live.contains(num(v)))throw new AssertionError("getRandom返回集合外元素");v="VALID_MEMBER";}}out.add(normal(v));}return out;}
  Class<?> c=type("Solution");Object obj=construct(c,List.of());String name=(String)meta.get("name");Method m=null;for(Method x:c.getDeclaredMethods())if(x.getName().equals(name)){m=x;break;}if(m==null)throw new IllegalArgumentException("找不到 "+name);m.setAccessible(true);Object[] args;
  if(id==141||id==142){Object head=convert(in.get(0),m.getGenericParameterTypes()[0]);List<Object> ns=nodes(head,"next");int pos=num(in.get(1));if(pos>=0)set(ns.get(ns.size()-1),"next",ns.get(pos));Object v=m.invoke(obj,head);return id==142?(v==null?-1:identityIndex(ns,v)):normal(v);}
  if(id==160){Class<?> lc=m.getParameterTypes()[0];Object a=convert(in.get(1),lc),b=convert(in.get(2),lc);List<Object> an=nodes(a,"next"),bn=nodes(b,"next");int sa=num(in.get(3)),sb=num(in.get(4));Object shared=num(in.get(0))==0?null:an.get(sa);if(shared!=null){if(sb==0)b=shared;else set(bn.get(sb-1),"next",shared);}Object v=m.invoke(obj,a,b);if(v!=null&&v!=shared)throw new AssertionError("交点必须为同一个节点对象");return v==null?null:normal(get(v,"val"));}
  if(id==236){Object root=convert(in.get(0),m.getGenericParameterTypes()[0]);Object a=find(root,num(in.get(1))),b=find(root,num(in.get(2)));Object v=m.invoke(obj,root,a,b);if(v!=null&&find(root,num(get(v,"val")))!=v)throw new AssertionError("LCA必须引用原树节点");return normal(get(v,"val"));}
  args=convertArgs(in,m.getGenericParameterTypes());Set<Object> originalSnapshot=Collections.newSetFromMap(new IdentityHashMap<>());Object beforeClone=null;if(id==138||id==133){collect(args[0],originalSnapshot,id==133);beforeClone=normal(args[0]);}Object v=m.invoke(obj,args);
  if(id==138||id==133){Set<Object> original=Collections.newSetFromMap(new IdentityHashMap<>());original.addAll(originalSnapshot);if(!Checker.equal(beforeClone,normal(args[0])))throw new AssertionError("深拷贝修改了原始结构");Set<Object> copy=Collections.newSetFromMap(new IdentityHashMap<>());collect(v,copy,id==133);for(Object x:copy)if(original.contains(x))throw new AssertionError("深拷贝与输入共享节点");}
  if(id==117){List<Object> out=new ArrayList<>();Queue<Object> q=new ArrayDeque<>();if(v!=null)q.add(v);while(!q.isEmpty()){List<Object> level=new ArrayList<>();int n=q.size();for(int i=0;i<n;i++){Object x=q.remove();level.add(x);for(String z:List.of("left","right")){Object ch=get(x,z);if(ch!=null)q.add(ch);}}for(int i=0;i<level.size();i++)if(get(level.get(i),"next")!=(i+1<level.size()?level.get(i+1):null))throw new AssertionError("next指针不是本层实际相邻节点");out.add(level.stream().map(x->{try{return get(x,"val");}catch(Exception e){throw new RuntimeException(e);}}).toList());}return out;}
  if(id==427){int n=((List<?>)in.get(0)).size();int[][] grid=new int[n][n];quad(v,grid,0,0,n);return normal(grid);}
  if(id==114){Object h=args[0];List<Object> ns=nodes(h,"right");for(Object x:ns)if(get(x,"left")!=null)throw new AssertionError("flatten后left非空");return ns.stream().map(x->{try{return get(x,"val");}catch(Exception e){throw new RuntimeException(e);}}).toList();}
  if(meta.containsKey("output")){Map<String,Object> out=Json.map(meta.get("output"));Object a=args[num(out.get("paramindex"))];if("ret".equals(out.get("size"))){int k=num(v);if(k<0||k>Array.getLength(a))throw new AssertionError("返回长度越界");List<Object> prefix=new ArrayList<>();for(int i=0;i<k;i++)prefix.add(normal(Array.get(a,i)));if(id==27)prefix.sort(Comparator.comparing(Json::stringify));return Map.of("length",k,"prefix",prefix);}return normal(a);}
  if(m.getReturnType()==void.class)return normal(args[0]);if(v==null&&Set.of("ListNode","TreeNode","Node").contains(m.getReturnType().getSimpleName()))return List.of();return normal(v);
 }
 static int identityIndex(List<?> ns,Object v){for(int i=0;i<ns.size();i++)if(ns.get(i)==v)return i;throw new AssertionError("返回的是新建节点，而不是原链表环入口");}
 void collect(Object x,Set<Object> set,boolean graph)throws Exception{if(x==null||!set.add(x))return;if(graph){for(Object n:(List<?>)get(x,"neighbors"))collect(n,set,true);}else{collect(get(x,"next"),set,false);collect(get(x,"random"),set,false);}}
 void quad(Object x,int[][] a,int r,int c,int n)throws Exception{if(x==null)throw new AssertionError("四叉树节点缺失");if(Boolean.TRUE.equals(get(x,"isLeaf"))){for(int i=r;i<r+n;i++)Arrays.fill(a[i],c,c+n,Boolean.TRUE.equals(get(x,"val"))?1:0);return;}if(n<2)throw new AssertionError("非法四叉树层级");int h=n/2;quad(get(x,"topLeft"),a,r,c,h);quad(get(x,"topRight"),a,r,c+h,h);quad(get(x,"bottomLeft"),a,r+h,c,h);quad(get(x,"bottomRight"),a,r+h,c+h,h);}
 Object normal(Object o)throws Exception{if(o==null||o instanceof String||o instanceof Number||o instanceof Boolean)return o;if(o instanceof Character)return o.toString();if(o.getClass().isArray()){List<Object>a=new ArrayList<>();for(int i=0;i<Array.getLength(o);i++)a.add(normal(Array.get(o,i)));return a;}if(o instanceof Iterable<?> it){List<Object>a=new ArrayList<>();for(Object x:it)a.add(normal(x));return a;}String n=o.getClass().getSimpleName();if(n.equals("ListNode")){List<Object>a=new ArrayList<>();Set<Object>seen=Collections.newSetFromMap(new IdentityHashMap<>());while(o!=null){if(!seen.add(o))throw new AssertionError("结果链表有环");a.add(get(o,"val"));o=get(o,"next");}return a;}if(n.equals("TreeNode")){List<Object>a=new ArrayList<>();Queue<Object>q=new LinkedList<>();Set<Object>seen=Collections.newSetFromMap(new IdentityHashMap<>());q.add(o);while(!q.isEmpty()){Object x=q.remove();if(x==null){a.add(null);continue;}if(!seen.add(x))throw new AssertionError("结果树重复引用或有环");a.add(get(x,"val"));q.add(get(x,"left"));q.add(get(x,"right"));}while(!a.isEmpty()&&a.get(a.size()-1)==null)a.remove(a.size()-1);return a;}if(n.equals("Node")&&id==138){List<Object>ns=nodes(o,"next");List<Object>a=new ArrayList<>();for(Object x:ns){Object rand=get(x,"random");a.add(Arrays.asList(get(x,"val"),rand==null?null:identityIndex(ns,rand)));}return a;}if(n.equals("Node")&&id==133){Set<Object>set=Collections.newSetFromMap(new IdentityHashMap<>());collect(o,set,true);TreeMap<Integer,Object> out=new TreeMap<>();for(Object x:set){List<Integer>edges=new ArrayList<>();for(Object y:(List<?>)get(x,"neighbors"))edges.add(num(get(y,"val")));Collections.sort(edges);if(out.put(num(get(x,"val")),edges)!=null)throw new AssertionError("图节点标识重复");}return new ArrayList<>(out.values());}throw new IllegalArgumentException("未适配输出 "+n);}
}
